// Type: ChangeEnding.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum ChangeEnding {
    Landed,
    NoChange,
    Cancelled,
    Failed(ChangeFailure),
}

// Record: ChangeEnding.
impl ChangeEnding {
    const SHAPE: &'static [skein_codec::bounds::Node] = &[
        skein_codec::bounds::Node::Scalar(0),
        skein_codec::bounds::Node::Scalar(0),
        skein_codec::bounds::Node::Scalar(0),
        skein_codec::bounds::Node::Named("ChangeFailure"),
        skein_codec::bounds::Node::Enum { variants: &[0, 1, 2, 3] },
    ];

    /// The record's encoded bound with every limit it reaches set to zero.
    pub const ENCODED_AT_ZERO: u64 = 5;
}

impl Record for ChangeEnding {
    type Limits = Limits;
    const TAIL: Path = paths::CHANGE_ENDING_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(DECLARATIONS, limits.values().as_slice(), CEILING_VALUES, "ChangeEnding")?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(DECLARATIONS, limits.values().as_slice(), CEILING_VALUES, "ChangeEnding")?.decoded)
    }

    #[cfg(debug_assertions)]
    fn decode(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let value = Self::read(limits, reader)?;
        if !reader.is_empty() {
            return Err(Self::TAIL.problem(skein_codec::Reason::Trailing));
        }
        Ok(value)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Landed => field::put(out, &[0], paths::CHANGE_ENDING_TAG),
            Self::NoChange => field::put(out, &[1], paths::CHANGE_ENDING_TAG),
            Self::Cancelled => field::put(out, &[2], paths::CHANGE_ENDING_TAG),
            Self::Failed(value) => { field::put(out, &[3], paths::CHANGE_ENDING_TAG)?; value.write(limits, out) },
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::CHANGE_ENDING_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Landed),
            1 => Ok(Self::NoChange),
            2 => Ok(Self::Cancelled),
            3 => Ok(Self::Failed(ChangeFailure::read(limits, reader)?)),
            4..=u8::MAX => Err(Problem { path: paths::CHANGE_ENDING_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

