// Type: ClosingStep.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum ClosingStep {
    Close,
    Land,
}

// Record: ClosingStep.
impl ClosingStep {
    const SHAPE: &'static [skein_codec::bounds::Node] = &[
        skein_codec::bounds::Node::Scalar(0),
        skein_codec::bounds::Node::Scalar(0),
        skein_codec::bounds::Node::Enum { variants: &[0, 1] },
    ];

    /// The record's encoded bound with every limit it reaches set to zero.
    pub const ENCODED_AT_ZERO: u64 = 1;
}

impl Record for ClosingStep {
    type Limits = Limits;
    const TAIL: Path = paths::CLOSING_STEP_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(DECLARATIONS, limits.values().as_slice(), CEILING_VALUES, "ClosingStep")?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(DECLARATIONS, limits.values().as_slice(), CEILING_VALUES, "ClosingStep")?.decoded)
    }

    #[cfg(debug_assertions)]
    fn decode(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let value = Self::read(limits, reader)?;
        if !reader.is_empty() {
            return Err(Self::TAIL.problem(skein_codec::Reason::Trailing));
        }
        Ok(value)
    }

    fn write(&self, _limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Close => field::put(out, &[0], paths::CLOSING_STEP_TAG),
            Self::Land => field::put(out, &[1], paths::CLOSING_STEP_TAG),
        }
    }

    fn read(_limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::CLOSING_STEP_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Close),
            1 => Ok(Self::Land),
            2..=u8::MAX => Err(Problem { path: paths::CLOSING_STEP_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

